content.text:
The `user` pod is crash-looping (repeated Failed and BackOff events, no recovery) and frontend's CheckUser calls fail fast. I have enough to answer.

```json
{
  "root_causes": [
    {
      "service": "user",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "metric", "sql": "SELECT service_name, metric, ROUND(AVG(value),2) avg_v, MIN(value) mn, MAX(value) mx, COUNT(*) n FROM abnormal_metrics WHERE service_name='user' AND metric='k8s.deployment.available' GROUP BY 1,2", "claim": "The user deployment shows 0 available replicas across the abnormal window, versus 1 in normal."},
        {"kind": "metric", "sql": "SELECT 'abn' p, COUNT(*) n, MAX(time) last_seen FROM abnormal_metrics WHERE service_name='user' AND metric='container.cpu.usage' UNION ALL SELECT 'norm', COUNT(*), MAX(time) FROM normal_metrics WHERE service_name='user' AND metric='container.cpu.usage'", "claim": "The user pod's container metrics stop after the normal period; none appear in the abnormal window."},
        {"kind": "log", "sql": "SELECT strftime(time,'%H:%M:%S') t, regexp_extract(message, '\"reason\":\"([^\"]+)\"', 1) reason, regexp_extract(message, '\"name\":\"([^\"]+)\"', 1) objname FROM abnormal_logs WHERE service_name='' AND message LIKE '%user-6cd54449b8%' ORDER BY time", "claim": "Kubernetes events show the user pod repeatedly Failed and in BackOff from 06:20 through 06:24, never recovering."},
        {"kind": "trace", "sql": "SELECT span_name, attr_status_code, COUNT(*) n, ROUND(quantile_cont(duration,0.5)/1e6,3) med_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name='user.User/CheckUser' GROUP BY 1,2", "claim": "All 44 frontend calls to user.User/CheckUser in the abnormal window return Error in about 0.02 ms, versus 115 successful calls in normal."}
      ]
    }
  ],
  "propagation": [
    {"from": "user", "to": "frontend", "evidence": [
      {"kind": "trace", "sql": "SELECT span_name, attr_http_response_status_code, COUNT(*) n, ROUND(quantile_cont(duration,0.5)/1e6,3) med_ms FROM abnormal_traces WHERE service_name='frontend' AND attr_span_kind='Server' AND attr_http_response_status_code>=500 GROUP BY 1,2", "claim": "Frontend /cinema, /museums, /restaurants and /reservation return HTTP 500 within about 0.05 ms, after the failed user check."}
    ]}
  ]
}
```

